class Flat { constructor(off) { this.off = off; }
  apply(t) { return Math.max(0, t - this.off); } }
class Checkout { constructor(rules) { this.rules = rules; }
  total(a) { return this.rules.reduce((s, rule) => rule.apply(s), a); } }
console.log(new Checkout([new Flat(30), new Flat(30)]).total(50));
